INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('on_this_day_events','c18ff826-4729-4cfc-887e-cb3f62ec9a28',NULL,1972,12,28,'War & Conflict',65,'{"id":"c18ff826-4729-4cfc-887e-cb3f62ec9a28","ad_day":28,"ad_date":null,"ad_year":1972,"bs_date":null,"country":null,"sources":[],"ad_month":12,"category":"War & Conflict","metadata":{"source_dataset":"lennovative/history_alert (Wikipedia-derived)","source_license":"Wikipedia-derived; retain linked-page attribution","translation_status":"translated"},"title_en":"The last scheduled day for induction into the military by the Selective Service System . Due to the fact that President Richard Nixon declared this day a national day of mourning due to former President Harry S Truman ''s death, approximately 300 men were not able to report due to most Federal offices being closed.  Since the draft was not resumed in 1973, they were never drafted.","title_ne":"सेलेक्टिभ सर्भिस सिस्टमद्वारा सेनामा भर्ना हुने अन्तिम निर्धारित दिन। पूर्व राष्ट्रपति ह्यारी एस ट्रुम्यानको मृत्युको कारण राष्ट्रपति रिचर्ड निक्सनले यस दिनलाई राष्ट्रिय शोक दिवस घोषणा गरेका कारण, धेरैजसो संघीय कार्यालयहरू बन्द भएका कारण लगभग ३०० पुरुषहरू रिपोर्ट गर्न सकेनन्। १९७३ मा मस्यौदा पुनः सुरु नभएकोले, तिनीहरूलाई कहिल्यै मस्यौदा गरिएको थिएन।","highlight":false,"image_url":null,"published":true,"created_at":"2026-09-19T03:30:45.118069+00:00","event_type":"event","importance":65,"source_url":"https://en.wikipedia.org/wiki/Selective_Service_System","summary_en":null,"summary_ne":null,"updated_at":"2026-09-19T03:30:45.118069+00:00","source_name":"User-provided historical dataset","country_code":null,"image_credit":null,"image_api_url":"https://en.wikipedia.org/w/api.php?action=query&prop=pageimages&format=json&piprop=thumbnail%7Coriginal&pithumbsize=1200&titles=Selective%20Service%20System&origin=*","image_license":null,"image_caption_en":null,"image_caption_ne":null,"image_page_title":"Selective Service System","source_record_id":"1228-1972-e-10rr18o","verification_status":"source-backed","event_date_precision":"day"}','2026-09-19T03:30:45.118069+00:00');
